    /// <summary>
    ///     Finds the specified record in the <c>METDutyRollValuesLine</c> table.
    /// </summary>
    /// <param name = "_site">InventSiteId</param>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_forupdate">true/false</param>
    /// <param name = "_validFrom">Start date of the record</param>
    /// <param name = "_validTo">End date or Expiry date of the record</param>
    /// <returns>
    ///     A record in the <c>METDutyRollValuesLine</c> table.
    /// </returns>
    static METDutyRollValuesLine find(InventSiteId  _site,
                                    ItemId          _itemId,
                                    boolean         _forupdate = false,
                                    utcdatetime     _validFrom = DateTimeUtil::utcNow(),
                                    utcdatetime     _validTo = DateTimeUtil::maxValue())
    {
        METDutyRollValuesLine dutyRollValuesLine;

        dutyRollValuesLine.selectForUpdate(_forupdate);
        select firstonly validtimestate(_validFrom, _validTo) dutyRollValuesLine
            index MainIdx
            where dutyRollValuesLine.Site == _site
                && dutyRollValuesLine.ItemId == _itemId;

        return dutyRollValuesLine;
    }

/// <summary>
/// Checks if a <c>METDutyRollValuesLine</c> record exists;
/// </summary>
/// <param name = "_site">InventSiteId</param>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_validFrom">Start date of the record</param>
/// <param name = "_validTo">End date or Expiry date of the record</param>
/// <returns>
/// true if a <c>METDutyRollValuesLine</c> record exists; otherwise, false.
/// </returns>
public static boolean exist(InventSiteId    _site, 
                            ItemId          _itemId, 
                            utcdatetime     _validFrom = DateTimeUtil::utcNow(),
                            utcdatetime     _validTo = DateTimeUtil::maxValue())
{
    return (select firstonly validtimestate(_validFrom, _validTo) RecId from METDutyRollValuesLine
        where METDutyRollValuesLine.Site == _site && METDutyRollValuesLine.ItemId == _itemId).RecId != 0;
}

    /// <summary>
    ///  sets the ValidFrom date for the current record in the <c>METDutyRollValuesLine</c> table.
    /// </summary>
    /// <param name = "_startDate">ValidFrom</param>
    public void setValidFrom(utcdatetime _startDate = DateTimeUtil::utcNow())
    {
        InventSite inventSite = InventSite::find(this.Site);

        utcdatetime siteLocalTime = DateTimeUtil::applyTimeZoneOffset( DateTimeUtil::utcNow(), inventSite.Timezone);
        utcdatetime validFrom     = DateTimeUtil::applyTimeZoneOffset(_startDate, inventSite.Timezone);

        if (validFrom == DateTimeUtil::minValue())
        {
            validFrom = siteLocalTime;
        }
        else if (DateTimeUtil::date(validFrom) == DateTimeUtil::date(siteLocalTime))
        {
            validFrom = DateTimeUtil::utcNow();

            utcdatetime validTo = DateTimeUtil::maxValue();
            METDutyRollValuesLine futureRecordsDeletion;

            /// Delete future records if any, to handle the scenario where their exists records with future date/s and their is exists an active record
            /// with expiry date and time is greater than current date and time. Since system does not allow overlapping records and without gaps between dates
            ttsbegin;
            while select forupdate validtimestate(validFrom, validTo) futureRecordsDeletion
                where futureRecordsDeletion.Site == this.Site
                    && futureRecordsDeletion.ItemId == this.ItemId
                    && futureRecordsDeletion.ValidFrom > validFrom
            {
                futureRecordsDeletion.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
                futureRecordsDeletion.delete();
            }
            ttscommit;
        }
        else if (DateTimeUtil::date(validFrom) > DateTimeUtil::date(siteLocalTime))
        {
            //validFrom = DateTimeUtil::newDateTime(DateTimeUtil::date(validFrom), 0);
            utcdatetime siteLocalMidnight = DateTimeUtil::newDateTime(DateTimeUtil::date(validFrom), 0);
            validFrom = DateTimeUtil::removeTimeZoneOffset(siteLocalMidnight, inventSite.Timezone);
            utcdatetime validTo = DateTimeUtil::maxValue();

            METDutyRollValuesLine existingRecord;
            while select forupdate validtimestate(validFrom, validTo) existingRecord
                index MainIdx
                where existingRecord.Site == this.Site
                    && existingRecord.ItemId == this.ItemId
                    && existingRecord.ValidFrom > validFrom
            {
                ttsbegin;
                existingRecord.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
                existingRecord.delete();
                ttscommit;
            }
        }

        this.ValidFrom = validFrom;

        if (this.ValidTo == DateTimeUtil::minValue())
        {
            this.ValidTo = DateTimeUtil::maxValue();
        }
    }

/// <summary>
///   Inserts a new record in the <c>METDutyRollValuesLine</c> table.
/// </summary>
public void insert()
{
    this.setValidFrom(this.ValidFrom);
    super();
}

    /// <summary>
    ///   modifiy the current record in the <c>METDutyRollValuesLine</c> table.
    /// </summary>
    /// <param name = "_fieldId">fieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldnum(METDutyRollValuesLine, ValidFrom):
                this.setValidFrom(this.ValidFrom);
                break;
            case fieldnum(METDutyRollValuesLine, ValidTo):
                if (this.ValidTo == DateTimeUtil::minValue())
                {
                    this.ValidTo = DateTimeUtil::maxValue();
                }
                break;
        }
    }
